steps.css:
body {
  max-width: 400px;
  margin: 30px auto;
  padding: 24px;
  font-family: Arial, sans-serif;
  color: #203853;
  background: #eff7ff;
  border: 2px solid #c2ddf2;
  border-radius: 20px;
  text-align: center;
}

h1 { color: #23578a; }
p { font-size: 1.15rem; }
button {
  margin: 5px;
  padding: 10px 16px;
  color: white;
  background: #286aa0;
  border: 0;
  border-radius: 10px;
  font-size: 1rem;
  cursor: pointer;
}
button:hover { background: #174b76; }

